{
  "conditions": {
    "basis_identification": {
      "status": "pass",
      "note": "Each major allegation (reclassification denial, harassment, exclusions, favoritism) is grounded in specific dates, incidents, and witness statements with internal record citations (IR page numbers)."
    },
    "reasoning_traceability": {
      "status": "review",
      "note": "The record presents complainant's allegations and respondent's denials with supporting witness testimony, but the investigative reasoning—how allegations were evaluated, weighed, or prioritized—is largely absent; the record is primarily a factual compilation without explicit investigative conclusions or logical connectors."
    },
    "cold_reviewer_clarity": {
      "status": "review",
      "note": "A reviewer years later could reconstruct the factual disputes (e.g., whether reclassification requests were made, whether exclusions occurred) from the record, but cannot determine from this text alone why the agency concluded the allegations were unproven, since the final decision text and investigative reasoning are omitted."
    },
    "accountability_support": {
      "status": "review",
      "note": "The record documents extensive conflicting evidence (complainant's detailed incident narratives versus respondent's denials and witness corroboration of both), but lacks explicit investigative findings on witness credibility, documentary verification (e.g., email records, personnel files), or the standard of proof applied to resolve contradictions."
    },
    "temporal_reconstructability": {
      "status": "pass",
      "note": "The record establishes a clear chronology from August 2015 (position duties) through November 2017 (retirement), with specific dates for allegations (November 2016 through November 2017), reclassification requests (April, June, July 2017), and exclusion incidents (January, April, May, July, August, November 2017)."
    }
  },
  "remediation_note": "The record requires explicit investigative findings that address each factual dispute (e.g., whether complainant made reclassification requests, whether exclusions were discriminatory), the evidentiary basis for resolving contradictions (documentary evidence, witness credibility assessments), and the reasoning that links evidence to the final conclusion that discrimination was not proven. A compliant version must include the investigator's analysis, not merely a compilation of allegations and denials.",
  "finding": {
    "ai_function": "summarization",
    "condition_triggered": "reasoning_traceability, cold_reviewer_clarity, accountability_support",
    "compliant_version": "A compliant investigative record background section must include: (1) explicit findings on each factual dispute (e.g., 'Based on email records and CW1's testimony, the investigator found that complainant did/did not request reclassification on the dates alleged'); (2) credibility assessments and documentary verification (e.g., whether email distribution lists were reviewed, whether position descriptions were retrieved); (3) the investigator's application of legal standards (e.g., whether similar situated comparators existed, whether timing supported causation); and (4) a summary of investigative reasoning that explains how the evidence as a whole supported or contradicted each element of the discrimination claim, not merely a recitation of what each party said."
  }
}
```
